-- M15.05–06, 24 original classroom scenario items; M15 theory, pedagogic ethics
-- and professional standard sources. No historical answer marker was copied as authority.
-- Seed idempotently; production deployment / migration requires explicit user approval.
BEGIN;
DO $m15$
DECLARE r record; v_lesson uuid; v_con uuid; v_sub uuid; v_group text; v_qid uuid; v_oid uuid; v_choices text[]; v_n integer; v_seed text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
(5,1,'Sinf rahbari o‘quvchining darsga qiziqishi pasayganini sezdi. Birinchi qadam?','O‘quvchi bilan individual suhbat o‘tkazib sabablarini aniqlash','Darhol barcha fanlardan qo‘shimcha nazorat belgilash','Ota-onasiga vaziyatni tushuntirmasdan tanbeh berish','Faqat bahoni pasaytirib, keyingi ishni kuzatmaslik','Muammoni aniqlash hamkorlik va yordam rejasidan avval keladi','qollash'),
(5,2,'Ota-ona bilan uchrashuvda eng konstruktiv muloqot qaysi?','Kuzatuv va faktlarni aytib, birgalikda yechimlarni muhokama qilish','Faqat bolaning xatolarini sanab, izohini tinglamasdan yakunlash','Baholarni boshqa o‘quvchilarning shaxsiy ma’lumoti bilan solishtirish','Ota-onaga hech qanday aniq ma’lumot bermasdan umumiy baho berish','Hamkorlik xolis fakt va umumiy qarorga tayanadi','qollash'),
(5,3,'Sinf rahbarining tarbiyaviy rejasi nimalarga mos bo‘lishi kerak?','Sinf ehtiyojlari, o‘quvchilar yoshi va tarbiyaviy maqsadlarga','Faqat bayramlar soni va maktab binosining bezatilishiga','Faqat o‘qituvchining shaxsiy qiziqishlari va bo‘sh vaqtiga','Faqat nazoratlar soni va jurnal sahifalari miqdoriga','Reja tarbiyaviy maqsad va sinfning real ehtiyojiga mos tuziladi','bilish'),
(5,4,'O‘quvchi sinf jamoasida chetda qolyapti. Eng maqbul chorasi qaysi?','Qiziqishini bilib, xavfsiz va muvaffaqiyatli kichik rol berish','Uni birdan murakkab jamoaviy vazifaning boshlig‘i qilish','Boshqalar bilan gaplashishga majburlab, vaziyatni oshkor qilish','Sinf ishlaridan butunlay chetlatib, vaqt o‘tishini kutish','Bosqichli qo‘llab-quvvatlash sinfga moslashishni yengillashtiradi','qollash'),
(5,5,'Bir o‘quvchining shaxsiy muammosi sinf yig‘ilishida oshkor qilindi. Muammo nimada?','Maxfiylik va o‘quvchining qadr-qimmatini hurmat qilish buzilgan','Sinfdagi barcha o‘quvchilarga teng so‘z berish talabi bajarilgan','Ota-onalar bilan hamkorlik to‘liq va samarali tashkil etilgan','Jamoada o‘zaro ishonch va xavfsizlik yanada mustahkamlangan','Individual ma’lumotlar bilan ehtiyotkor muomala qilish kerak','mulohaza'),
(5,6,'Fan o‘qituvchilari o‘quvchining o‘zlashtirishi haqida turli ma’lumot berdi. Nima qilish kerak?','Ma’lumotlarni taqqoslab, kuzatuv va yordam rejasi tuzish','Faqat bir fikrni tanlab, boshqa ma’lumotlarni e’tiborsiz qoldirish','Hech qanday dalilsiz darhol qat’iy xulosa chiqarish','O‘quvchi bilan suhbatlashmasdan, masalani yopish','Hamkorlik bir nechta manbani xolis tahlil qilishni talab etadi','mulohaza'),
(5,7,'Sinf jamoasini shakllantirishda qaysi yondashuv samarali?','O‘zaro hurmat va mas’uliyatga asoslangan hamkorlik yaratish','Sinfda faqat yetakchi o‘quvchilar fikrini hisobga olish','Har qanday o‘zaro yordamni faqat musobaqaga aylantirish','Vazifani bajarishda barcha tashabbuslarni cheklash','Jamoa tarbiyasi o‘zaro hurmat va ishtirokni qo‘llaydi','bilish'),
(5,8,'Ota-onalar yig‘ilishi faqat tanbeh bilan o‘tdi. Kamchilik qaysi?','Hamkorlik va ijobiy yechim izlash imkoniyatidan foydalanilmagan','Sinf faoliyati barcha ehtiyojlarni hisobga olgan tarzda baholangan','O‘quvchilarning kuchli jihatlari yetarli darajada muhokama qilingan','Ota-onalar fikri tinglanib, kelishilgan reja tuzilgan','Uchrashuv natijaga yo‘naltirilgan hamkorlikni rivojlantirishi kerak','mulohaza'),
(5,9,'Davomat o‘zgarishi kuzatilsa sinf rahbari nima qiladi?','Sababni aniqlab, ota-ona bilan hamkorlik qiladi','Faqat jurnalni to‘ldirib, boshqa choralarni to‘xtatadi','Sababini bilmay, o‘quvchini umumiy majlisda koyiydi','Faqat boshqa fan o‘qituvchisiga javobgarlikni yuklaydi','Davomat monitoringi yordam va hamkorlik bilan bog‘lanadi','qollash'),
(5,10,'Sinf soati uchun mavzu tanlashda nimaga tayanish zarur?','Tarbiyaviy maqsad va sinfda kuzatilgan dolzarb ehtiyojlarga','Faqat o‘qituvchining avvalgi yilgi shaxsiy sevimli mavzusiga','Faqat darslikning eng uzun va murakkab paragrafiga','Faqat kundalikning oxirgi sahifasidagi yozuvlarga','Sinf soati tarbiyaviy ehtiyojlarga mos rejalashtiriladi','bilish'),
(5,11,'Sinfda nizo paydo bo‘ldi. Rahbarning birinchi vazifasi qaysi?','Tomonlarni xolis tinglab, holatni tushunish va xavfsizlikni saqlash','Tomonlardan birini dalilsiz aybdor deb e’lon qilish','Nizoni muhokamasiz jamoa oldida keskinlashtirish','Vaziyatga e’tibor bermasdan, nizoning kuchayishini kutish','Xolis tinglash nizoli vaziyatga pedagogik yondashuvning boshlanishidir','qollash'),
(5,12,'Ota-ona va fan o‘qituvchisida turli kutishlar mavjud. Qanday yo‘l samarali?','Umumiy maqsadni aniqlab, kelishilgan harakat rejasini tuzish','Bir tomonning talabini boshqasini eshitmay majburan qo‘llash','Uchrashuvni faktlarni tekshirmasdan yakunlangan deb hisoblash','O‘quvchining fikrini tinglashni butunlay cheklash','Hamkorlik o‘quvchi manfaatidagi kelishilgan maqsadga tayanadi','mulohaza'),
(5,13,'O‘quvchining ijobiy o‘zgarishi ota-onaga bildirildi. Bu nimani mustahkamlaydi?','Ishonch, hamkorlik va bolaning rivojlanishini qo‘llab-quvvatlashni','Faqat hisobot sahifalari sonini ko‘paytirishni','Faqat o‘quvchi bahosini boshqa sinflar bilan solishtirishni','Faqat yig‘ilish vaqtini qisqartirishni','Ijobiy qayta aloqa ota-ona bilan ishonchli hamkorlikni kuchaytiradi','qollash'),
(6,1,'O‘quvchi noto‘g‘ri javob berdi. O‘qituvchi uni kamsitmay to‘g‘ri yo‘l ko‘rsatdi. Bu nima?','Pedagogik takt — vaziyatda hurmat va me’yorni saqlash','Akademik qobiliyat — fan bo‘yicha chuqur bilimga ega bo‘lish','Didaktik prinsip — ta’limning umumiy qonun-qoidasi','Tashkiliy reja — mashg‘ulot vaqtini oldindan belgilash','Pedagogik takt o‘quvchi qadrini hurmat qilib ta’sir etishni talab qiladi','qollash'),
(6,2,'O‘qituvchi darsdan keyin usullarini baholab, yangisini rejaladi. Bu qanday jarayon?','Refleksiya — o‘z faoliyatini tahlil qilib takomillashtirish','Diagnostika — o‘quvchining boshlang‘ich bilimini o‘lchash','Ko‘rgazmalilik — mavzuni tasviriy vositalar bilan tushuntirish','Nazorat — berilgan topshiriq natijasini baholash','Refleksiya o‘z faoliyatidan xulosa chiqarishga xizmat qiladi','bilish'),
(6,3,'O‘qituvchi nutqida g‘oyalar izchil va sabab-oqibatli bayon etildi. Qaysi sifat?','Nutqning mantiqiyligi — fikrlar orasidagi izchil bog‘lanish','Nutqning emotsionalligi — tinglovchida hissiyot uyg‘otish','Nutqning ifodaliligi — ohang yordamida ta’sirni oshirish','Nutqning aniqligi — so‘z tanlovida noaniqlikka yo‘l qo‘ymaslik','Fikrlar o‘zaro mantiqan ulanib borishi mantiqiylikdir','bilish'),
(6,4,'Sinfda o‘qituvchi ovoz kuchini vaziyatga moslab boshqardi. Bu nimaga kiradi?','Pedagogik texnika — ovoz va ifoda vositalarini boshqarish','Pedagogik refleksiya — darsdan keyin o‘zini tahlil qilish','Didaktik tamoyil — ta’lim jarayoniga qo‘yilgan umumiy talab','Sinf diagnostikasi — dastlabki tayyorgarlikni aniqlash','Ovoz va ifodani boshqarish pedagogik texnikaga oid','qollash'),
(6,5,'O‘qituvchi ikki o‘quvchiga turlicha munosabat qildi, chunki biri unga yaqinroq. Nima buzilgan?','Pedagogik etikaning adolatlilik va xolislik talabi buzilgan','Pedagogik texnikaning ovoz diapazoni talabi bajarilgan','Didaktik tamoyilning ko‘rgazmalilik sharti bajarilgan','Metodik rejaning mavzuni qismlarga ajratish talabi bajarilgan','O‘qituvchi shaxsiy yaqinlikdan qat’i nazar xolis bo‘lishi kerak','mulohaza'),
(6,6,'Darsda o‘qituvchi o‘quvchining fikrini tinglab, muloyim javob berdi. Asosiy yondashuv?','Pedagogik etika — muloqotda hurmat va muloyimlikni saqlash','Didaktik reja — mavzu bosqichlarini oldindan belgilash','Nazorat mezoni — javobga qo‘yiladigan balni hisoblash','Tarbiyaviy hisobot — sinf tadbirlarini hujjatlashtirish','Hurmatli muloqot pedagogik etikaga xos','qollash'),
(6,7,'O‘qituvchi o‘z fikrini tez aytadi, lekin atamalar noaniq. Qaysi sifatni tuzatish kerak?','Nutqning aniqligi — tushunchani bir ma’noda ifodalash','Nutqning balandligi — tinglovchiga ovozni kuchaytirish','Nutqning sur’ati — gapirish tezligini oshirish','Nutqning emotsiyasi — hissiy ta’sirni kuchaytirish','Tez gapirish nutqning mazmuniy aniqligini kafolatlamaydi','mulohaza'),
(6,8,'O‘qituvchi jamoa bilan dars tajribasini muhokama qilib xulosa chiqardi. Qaysi refleksiya belgisi?','Hamkorlikdagi refleksiya — tajribani birgalikda tahlil qilish','Individual baholash — faqat yakka test natijasini ko‘rish','Me’yoriy nazorat — faqat dasturdagi talabni tekshirish','Tashkiliy kuzatuv — faqat davomatni nazorat qilish','Hamkasblar bilan faoliyatni birga tahlil qilish refleksiv amaliyotdir','qollash'),
(6,9,'O‘qituvchi tanqid bildirayotganda vaziyat va bolaning hissiyotini hisobga oldi. Qaysi sifat?','Pedagogik nazokat — ta’sirda o‘rinli me’yorni his qilish','Akademik tayyorgarlik — o‘quv fani faktlarini chuqur bilish','Didaktik loyihalash — o‘quv mavzularini rejalashtirish','Maktab menejmenti — resurslarni muvofiqlashtirish','Pedagogik takt tanqidda ham hurmatni saqlashni talab etadi','qollash'),
(6,10,'O‘qituvchi darsdagi xatoni yashirib, keyingi darsni o‘zgartirmadi. Qaysi imkoniyat boy berildi?','Refleksiya asosida faoliyatni yaxshilash imkoniyati boy berildi','Tashqi tekshiruvni o‘tkazmasdan yakunlash imkoniyati boy berildi','Dars rejasini umuman yozmasdan ishlash imkoniyati boy berildi','O‘quvchilarni tanbehsiz baholash imkoniyati boy berildi','Refleksiya xatodan saboq olib keyingi ishni tuzatishga xizmat qiladi','mulohaza'),
(6,11,'O‘quvchi savoliga o‘qituvchi sodda va ravon jumlalar bilan javob berdi. Qaysi talab?','Nutqning tushunarliligi — tinglovchiga mos ifodalash','Nutqning murakkabligi — atamalar sonini oshirish','Nutqning tezligi — javobni imkon qadar shoshirish','Nutqning balandligi — ovozni doim bir xil tutish','Tushunarli bayon pedagogik nutq sifatidir','qollash')
 ) t(topic_order,seed_no,stem,answer,wrong_1,wrong_2,wrong_3,explanation,cognitive)
 LOOP
  SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE m.code='M15' AND l.order_idx=r.topic_order AND l.status='published';
  SELECT c.id,c.subject_id,c.group_code INTO STRICT v_con,v_sub,v_group FROM public.constructs c WHERE c.code='PM.GEN.'||lpad(r.topic_order::text,2,'0') AND c.is_active;
  v_seed := 'm15-y1-20261018:'||r.topic_order::text||':'||r.seed_no::text;
  v_qid := md5(v_seed)::uuid;
  INSERT INTO public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id,is_generated)
  VALUES(v_qid,v_sub,v_con,v_group,'Y1'::public.question_format,r.cognitive::public.cognitive_level,3,r.stem,'review'::public.content_status,'authored:m15-topictest-20261018:'||r.topic_order::text||':'||r.seed_no::text,v_lesson,false)
  ON CONFLICT (id) DO NOTHING;
  v_choices := ARRAY[r.answer,r.wrong_1,r.wrong_2,r.wrong_3];
  FOR v_n IN 1..4 LOOP
    v_oid := md5(v_seed||':option:'||v_n::text)::uuid;
    INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_oid,v_qid,'a',v_n,v_choices[v_n]) ON CONFLICT(id) DO NOTHING;
  END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(v_qid,jsonb_build_object('correct_option_id',md5(v_seed||':option:1')::uuid),r.explanation)
  ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END
$m15$;
COMMIT;